package aarnav100.developer.biblescroll.core.plans

import kotlin.math.abs
import kotlin.math.ceil

/**
 * Splitting a reading into days. A line-for-line port of pipeline/src/pipeline/plans/splitting.py (the
 * reference); golden vectors generated by the pipeline (splitting_vectors.json) keep the two identical.
 *
 * [words] is each verse's word count in reading order; [tiers] says how good a stopping place the end of each
 * verse is ([Tier]). Ties always go to the earliest index, as in Python's min().
 */
object PlanSplitter {
    object Tier {
        const val NONE = 0
        const val SENTENCE = 1
        const val PARAGRAPH = 2
        const val CHAPTER = 3
    }

    const val WORDS_PER_MINUTE = 200
    const val MAX_OVER = 1.5
    val SNAP_STEPS = doubleArrayOf(0.35, 0.25, 0.15, 0.08, 0.0)
    private val TIERS_TRIED = intArrayOf(Tier.CHAPTER, Tier.PARAGRAPH, Tier.SENTENCE)

    private fun reach(tier: Int): Double = if (tier == Tier.SENTENCE) 0.5 else 1.0

    /** Index of the last verse of each day but the final one (size days - 1). */
    fun splitCuts(words: IntArray, tiers: IntArray, days: Int, tolerance: Double): IntArray {
        require(days >= 1) { "days must be >= 1" }
        require(days <= words.size) { "Can't split ${words.size} verses into $days days" }
        require(tiers.size == words.size)
        val cumulative = LongArray(words.size)
        var running = 0L
        for (i in words.indices) {
            running += words[i]
            cumulative[i] = running
        }
        val total = cumulative.last()
        val perDay = total.toDouble() / days
        val cuts = IntArray(days - 1)
        var previous = -1
        for (k in 1 until days) {
            val target = (total * k).toDouble() / days
            val latest = words.size - 1 - (days - k)
            var cut = -1
            for (tier in TIERS_TRIED) {
                val limit = tolerance * reach(tier) * perDay
                var best = -1
                var bestDistance = Double.MAX_VALUE
                for (i in previous + 1..latest) {
                    if (tiers[i] < tier) continue
                    val distance = abs(cumulative[i] - target)
                    if (distance < bestDistance) {
                        best = i
                        bestDistance = distance
                    }
                }
                if (best >= 0 && bestDistance <= limit) {
                    cut = best
                    break
                }
            }
            if (cut < 0) {
                var bestDistance = Double.MAX_VALUE
                for (i in previous + 1..latest) {
                    val distance = abs(cumulative[i] - target)
                    if (distance < bestDistance) {
                        cut = i
                        bestDistance = distance
                    }
                }
            }
            cuts[k - 1] = cut
            previous = cut
        }
        return cuts
    }

    fun dayWords(words: IntArray, cuts: IntArray): IntArray {
        val out = IntArray(cuts.size + 1)
        var day = 0
        for (i in words.indices) {
            out[day] += words[i]
            if (day < cuts.size && i == cuts[day]) day++
        }
        return out
    }

    /** Rounded-up average minutes a day. Summed in order, like Python's sum(), so rounding matches. */
    fun estimateMinutes(dayWords: IntArray): Int {
        var sum = 0.0
        for (w in dayWords) sum += w.toDouble() / WORDS_PER_MINUTE
        return maxOf(1, ceil(sum / dayWords.size).toInt())
    }

    fun withinLimit(dayWords: IntArray): Boolean {
        val limit = estimateMinutes(dayWords) * MAX_OVER
        return dayWords.all { it.toDouble() / WORDS_PER_MINUTE <= limit }
    }

    fun chapterCuts(tiers: IntArray): IntArray = (0 until tiers.size - 1).filter { tiers[it] >= Tier.CHAPTER }.toIntArray()

    /** A chapter a day when the reading has exactly [days] chapters and it fits; else the loosest snapping that fits. */
    fun planCuts(words: IntArray, tiers: IntArray, days: Int): IntArray {
        val chapters = chapterCuts(tiers)
        if (chapters.size == days - 1 && withinLimit(dayWords(words, chapters))) return chapters
        var cuts = IntArray(0)
        for (tolerance in SNAP_STEPS) {
            cuts = splitCuts(words, tiers, days, tolerance)
            if (withinLimit(dayWords(words, cuts))) return cuts
        }
        return cuts
    }

    /** Days needed at [minutes] a day (rounded up), at least 1 and at most one verse a day. */
    fun daysForMinutes(totalWords: Long, minutes: Int, verses: Int): Int {
        require(minutes >= 1) { "minutes must be >= 1" }
        val days = ceil(totalWords.toDouble() / (minutes * WORDS_PER_MINUTE)).toInt()
        return maxOf(1, minOf(verses, days))
    }
}
